set-variable.value:
@{
            try {
                var contentType = context.Request.Headers.GetValueOrDefault("Content-Type", "");
                var lengthText = context.Request.Headers.GetValueOrDefault("Content-Length", "0");
                if (lengthText.Length > 8 || (lengthText.Length == 8 && string.CompareOrdinal(lengthText, "25000000") > 0)) { return ""; }
                var model = "";
                if (contentType.StartsWith("multipart/form-data", StringComparison.OrdinalIgnoreCase)) {
                    var text = context.Request.Body.As<string>(preserveContent: true);
                    var m = System.Text.RegularExpressions.Regex.Match(text, "name=\"model\"[^\\r\\n]*\\r?\\n(?:[^\\r\\n]+\\r?\\n)*\\r?\\n([^\\r\\n]+)");
                    model = m.Success ? m.Groups[1].Value.Trim() : "";
                } else {
                    var body = context.Request.Body.As<JObject>(preserveContent: true);
                    model = (string)body["model"] ?? "";
                }
                return System.Text.RegularExpressions.Regex.IsMatch(model, "^[A-Za-z0-9._-]{1,64}$") ? model : "";
            } catch {
                return "";
            }
        }

@{
            try {
                var contentType = context.Request.Headers.GetValueOrDefault("Content-Type", "");
                if (contentType.StartsWith("multipart/form-data", StringComparison.OrdinalIgnoreCase)) {
                    try {
                        var bm = System.Text.RegularExpressions.Regex.Match(contentType, "boundary=(?:\"([^\"]+)\"|([^;\\s]+))", System.Text.RegularExpressions.RegexOptions.IgnoreCase);
                        if (!bm.Success) { return true; }
                        var boundary = bm.Groups[1].Success ? bm.Groups[1].Value : bm.Groups[2].Value;
                        var text = context.Request.Body.As<string>(preserveContent: true);
                        var found = 0;
                        var enabled = false;
                        foreach (var part in text.Split(new[] { "--" + boundary }, StringSplitOptions.None)) {
                            var sepLen = 4;
                            var sep = part.IndexOf("\r\n\r\n", StringComparison.Ordinal);
                            if (sep < 0) { sepLen = 2; sep = part.IndexOf("\n\n", StringComparison.Ordinal); }
                            if (sep < 0) { continue; }
                            var named = System.Text.RegularExpressions.Regex.IsMatch(part.Substring(0, sep), "(^|\\n)Content-Disposition:[^\\r\\n]*[;\\s]name=(\"web_grounding\"|web_grounding([;\\s]|$))", System.Text.RegularExpressions.RegexOptions.IgnoreCase);
                            if (!named) { continue; }
                            found++;
                            var gv = part.Substring(sep + sepLen).Trim().ToLowerInvariant();
                            if (gv != "false" && gv != "0") { enabled = true; }
                        }
                        return enabled || found > 1;
                    } catch {
                        return true;
                    }
                }
                var body = context.Request.Body.As<JObject>(preserveContent: true);
                var token = body["web_grounding"];
                if (token == null) { return false; }
                return token.ToString().ToLowerInvariant() == "true";
            } catch {
                return false;
            }
        }

emit-metric.value:
@{
                    try {
                        var body = context.Response.Body.As<JObject>(preserveContent: true);
                        var data = body["data"] as JArray;
                        return data != null ? (double)data.Count : 1.0;
                    } catch {
                        return 1.0;
                    }
                }
